SELECT i.* , c.companyname as investor_name, CASE WHEN relationshiptypeid IN(24, 26, 157, 301, 148, 69) THEN 'Current Investor' WHEN relationshiptypeid IN(25, 27, 158, 302, 339) THEN 'Prior Investor' END AS 'RelationShipType', (SELECT description FROM master WHERE masterid = relationshiptypeid) AS relationshiptypedesc, c.companytypeid as companytypeid FROM investor i inner JOIN company c ON i.relativecompanyid = c.companyid where targetcompanyid = targetCompanyId and i.relationshiptypeid in (25, 27, 158, 302, 339, 24, 26, 157, 301, 148, 69)